    self.salvarHistorico = function (historico) {
        util.sessao.definir("historico_consulta_processo", historico, true);
    };

    self.recuperarHistorico = function () {
        var hist = util.sessao.recuperar("historico_consulta_processo", true);
        return hist || [];
    };

    self.processoJaEstaNoHistorico = function (proc) {
        if (!proc || !proc.id) {
            return;
        }

        // verifica se o processo já não está presente no historico
        var found = self.recuperarHistorico().find(function (item) {
            if (item.id == proc.id) {
                return item;
            }
        });

        return found ? true : false;
    };

    self.adicionarProcessoNoHistorico = function (proc) {
        if (!proc) {
            return;
        }

        if (!self.processoJaEstaNoHistorico()) {
            var hist = self.recuperarHistorico();
            hist.push(proc);
            self.salvarHistorico(hist);
        }
    };

    self.removerProcessoDoHistorico = function (proc) {
        if (!proc || !proc.id) {
            return;
        }

        // retorna o array de  historico já sem o item a ser removido
        var hist = self.recuperarHistorico().filter(function (item) {
            if (item.id != proc.id) {
                return item;
            }
        });

        self.salvarHistorico(hist);
    };

